#!/usr/bin/env python3
from __future__ import annotations

from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
MODULE = ROOT / "src/domains/creator/vrm/studio-vrm-component-psd.ts"


def replace_once(source: str, old: str, new: str) -> str:
    count = source.count(old)
    if count != 1:
        raise RuntimeError(f"expected exactly one match, found {count}: {old[:120]!r}")
    return source.replace(old, new, 1)


source = MODULE.read_text(encoding="utf-8")
source = replace_once(
    source,
    '''const DEFAULT_BLEND_MODES: Readonly<Record<StudioVrmComponentPassKind, StudioVrmComponentPsdBlendMode>> = Object.freeze({\n''',
    '''const COMPONENT_PASS_KINDS = new Set<StudioVrmComponentPassKind>(GROUP_ORDER);\nconst COMPONENT_BLEND_MODES = new Set<StudioVrmComponentPsdBlendMode>([\n  "normal",\n  "multiply",\n  "screen",\n  "overlay",\n  "soft light",\n]);\n\nconst DEFAULT_BLEND_MODES: Readonly<Record<StudioVrmComponentPassKind, StudioVrmComponentPsdBlendMode>> = Object.freeze({\n''',
)
source = replace_once(
    source,
    '''    if (pass.width !== scene.width || pass.height !== scene.height) {\n      throw new Error(`component pass ${id} must match the linked scene dimensions`);\n    }\n    const expectedBytes = scene.width * scene.height * 4;\n    if (!(pass.rgba instanceof Uint8Array) || pass.rgba.byteLength !== expectedBytes) {\n      throw new Error(`component pass ${id} must contain exactly ${expectedBytes} RGBA bytes`);\n    }\n    return Object.freeze({\n''',
    '''    if (!COMPONENT_PASS_KINDS.has(pass.kind)) {\n      throw new Error(`component pass ${id} has an unsupported pass kind`);\n    }\n    if (pass.width !== scene.width || pass.height !== scene.height) {\n      throw new Error(`component pass ${id} must match the linked scene dimensions`);\n    }\n    const expectedBytes = scene.width * scene.height * 4;\n    if (\n      !(pass.rgba instanceof Uint8Array || pass.rgba instanceof Uint8ClampedArray)\n      || pass.rgba.byteLength !== expectedBytes\n    ) {\n      throw new Error(`component pass ${id} must contain exactly ${expectedBytes} RGBA bytes`);\n    }\n    const blendMode = pass.blendMode ?? DEFAULT_BLEND_MODES[pass.kind];\n    if (!COMPONENT_BLEND_MODES.has(blendMode)) {\n      throw new Error(`component pass ${id} has an unsupported blend mode`);\n    }\n    return Object.freeze({\n''',
)
source = replace_once(
    source,
    '''      blendMode: pass.blendMode ?? DEFAULT_BLEND_MODES[pass.kind],\n''',
    '''      blendMode,\n''',
)
source = replace_once(
    source,
    '''  const digest = await subtle.digest("SHA-256", bytes);\n''',
    '''  const input = new Uint8Array(bytes.byteLength);\n  input.set(bytes);\n  const digest = await subtle.digest("SHA-256", input.buffer);\n''',
)
MODULE.write_text(source, encoding="utf-8")

TEST = ROOT / "src/domains/creator/vrm/studio-vrm-component-psd.test.ts"
TEST.write_text('''import { describe, expect, it } from "vitest";\n\nimport {\n  buildStudioVrmComponentPsdDocument,\n  createStudioVrmLinkedRenderManifest,\n  studioVrmLinkedRenderNeedsRefresh,\n  writeStudioVrmComponentPsd,\n  type StudioVrmComponentPass,\n  type StudioVrmLinkedSceneDescriptor,\n} from "./studio-vrm-component-psd";\n\nconst SCENE: StudioVrmLinkedSceneDescriptor = Object.freeze({\n  sceneId: "scene-character-001",\n  sceneRevision: 14,\n  cameraId: "portrait-camera",\n  renderPresetId: "toon-clean-v2",\n  width: 2,\n  height: 2,\n});\n\nfunction rgba(seed: number, clamped = false): Uint8Array | Uint8ClampedArray {\n  const values = Array.from({ length: 16 }, (_, index) => (seed + index * 17) % 256);\n  return clamped ? new Uint8ClampedArray(values) : new Uint8Array(values);\n}\n\nfunction pass(overrides: Partial<StudioVrmComponentPass> = {}): StudioVrmComponentPass {\n  return Object.freeze({\n    id: "hair-color",\n    kind: "hair",\n    name: "Hair / Color",\n    width: 2,\n    height: 2,\n    rgba: rgba(11),\n    ...overrides,\n  });\n}\n\ndescribe("component-aware VRM PSD export", () => {\n  it("builds stable semantic groups with webtoon-oriented blend defaults", () => {\n    const document = buildStudioVrmComponentPsdDocument(SCENE, [\n      pass(),\n      pass({ id: "line", kind: "line", name: "Ink", rgba: rgba(31) }),\n      pass({ id: "shadow", kind: "shadow", name: "Shadow", rgba: rgba(57) }),\n      pass({ id: "highlight", kind: "highlight", name: "Highlight", rgba: rgba(83) }),\n    ]) as unknown as { children: Array<{ children: Array<{ name: string; children: Array<{ blendMode: string }> }> }> };\n\n    expect(document.children[0]?.children.map((group) => group.name)).toEqual([\n      "01 Line",\n      "02 Highlight",\n      "05 Hair",\n      "08 Shadow",\n    ]);\n    expect(document.children[0]?.children[0]?.children[0]?.blendMode).toBe("multiply");\n    expect(document.children[0]?.children[1]?.children[0]?.blendMode).toBe("screen");\n    expect(document.children[0]?.children[3]?.children[0]?.blendMode).toBe("multiply");\n  });\n\n  it("accepts both Uint8 and Uint8Clamped RGBA buffers and writes a real PSD", async () => {\n    const result = await writeStudioVrmComponentPsd(SCENE, [\n      pass({ rgba: rgba(101, true) }),\n      pass({ id: "skin", kind: "skin", name: "Skin", rgba: rgba(127) }),\n    ]);\n\n    expect(new TextDecoder("ascii").decode(result.bytes.subarray(0, 4))).toBe("8BPS");\n    expect(result.bytes.byteLength).toBeGreaterThan(26);\n    expect(result.manifest.kind).toBe("toonstudio.vrm-linked-render");\n    expect(result.manifest.passes).toHaveLength(2);\n    expect(result.manifest.passes.every((receipt) => /^[0-9a-f]{64}$/u.test(receipt.sha256))).toBe(true);\n    expect(JSON.parse(result.manifestJson)).toEqual(result.manifest);\n  });\n\n  it("produces deterministic pass receipts independent of the source typed-array class", async () => {\n    const left = await createStudioVrmLinkedRenderManifest(SCENE, [pass({ rgba: rgba(3) })]);\n    const right = await createStudioVrmLinkedRenderManifest(SCENE, [pass({ rgba: rgba(3, true) })]);\n    expect(right).toEqual(left);\n  });\n\n  it("marks only scene, camera, render preset, revision, or dimensions changes stale", async () => {\n    const manifest = await createStudioVrmLinkedRenderManifest(SCENE, [pass()]);\n    expect(studioVrmLinkedRenderNeedsRefresh(manifest, { ...SCENE })).toBe(false);\n    expect(studioVrmLinkedRenderNeedsRefresh(manifest, { ...SCENE, sceneRevision: 15 })).toBe(true);\n    expect(studioVrmLinkedRenderNeedsRefresh(manifest, { ...SCENE, cameraId: "close-up" })).toBe(true);\n    expect(studioVrmLinkedRenderNeedsRefresh(manifest, { ...SCENE, renderPresetId: "toon-soft" })).toBe(true);\n    expect(studioVrmLinkedRenderNeedsRefresh(manifest, { ...SCENE, width: 3 })).toBe(true);\n    expect(studioVrmLinkedRenderNeedsRefresh(null, SCENE)).toBe(true);\n  });\n\n  it("fails closed on ambiguous, oversized, malformed, or duplicate package input", () => {\n    expect(() => buildStudioVrmComponentPsdDocument(SCENE, [])).toThrow(/at least one/u);\n    expect(() => buildStudioVrmComponentPsdDocument(SCENE, [pass(), pass()])).toThrow(/duplicate/u);\n    expect(() => buildStudioVrmComponentPsdDocument(SCENE, [pass({ width: 3 })])).toThrow(/dimensions/u);\n    expect(() => buildStudioVrmComponentPsdDocument(SCENE, [pass({ rgba: new Uint8Array(4) })])).toThrow(/16 RGBA bytes/u);\n    expect(() => buildStudioVrmComponentPsdDocument(\n      { ...SCENE, width: 16_384, height: 16_384 },\n      [pass({ width: 16_384, height: 16_384 })],\n    )).toThrow(/64-megapixel/u);\n    expect(() => buildStudioVrmComponentPsdDocument(SCENE, [\n      pass({ kind: "unknown" as StudioVrmComponentPass["kind"] }),\n    ])).toThrow(/unsupported pass kind/u);\n  });\n});\n''', encoding="utf-8")

DOC = ROOT / "docs/studio/vrm-component-psd-linked-render.md"
DOC.parent.mkdir(parents=True, exist_ok=True)
DOC.write_text('''# VRM component PSD and linked rerender contract\n\n## Product goal\n\nA 3D character capture is not flattened into one disposable PNG. ToonStudio exports editable line, base-colour, shadow, highlight, eye, hair, skin, clothing, prop, depth, and material-ID passes in a semantic PSD hierarchy, accompanied by a content-addressed linked-render manifest.\n\n## PSD hierarchy\n\n```text\nCharacter\n├─ 01 Line                 multiply\n├─ 02 Highlight            screen\n├─ 03 Props                normal\n├─ 04 Clothes              normal\n├─ 05 Hair                 normal\n├─ 06 Eyes                 normal\n├─ 07 Skin                 normal\n├─ 08 Shadow               multiply\n├─ 09 Base Color           normal\n├─ 90 Material ID          hidden/utility\n└─ 91 Depth                hidden/utility\n```\n\nEach render pass may contain multiple named layers. Export keeps the requested visibility, opacity, and supported blend mode while sanitizing non-portable layer names.\n\n## Linked-render invalidation\n\nThe sidecar manifest records the scene ID and revision, active camera, render preset, output dimensions, and SHA-256 for every pass. An existing PSD render is stale when any of these scene descriptors changes. It is not marked stale merely because UI layout, selection, or unrelated document metadata changes.\n\n## Safety limits\n\n- all passes must have exactly the same dimensions;\n- every pass must carry an exact RGBA byte count;\n- duplicate pass IDs are rejected;\n- unsupported pass kinds and blend modes fail closed;\n- output is capped at 64 megapixels;\n- PSD output must begin with the real `8BPS` signature;\n- each pass receives an immutable SHA-256 receipt.\n\n## Integration sequence\n\n1. Render the current VRM scene into semantic passes.\n2. Call `writeStudioVrmComponentPsd` to generate the PSD and sidecar manifest.\n3. Insert or download both artifacts as one user operation.\n4. Persist the manifest with the linked scene layer.\n5. Use `studioVrmLinkedRenderNeedsRefresh` to show a rerender badge after scene, camera, preset, revision, or size changes.\n6. A user may unlink and bake the PSD group; baked groups no longer follow the scene revision.\n''', encoding="utf-8")

print("Finalized component-aware VRM PSD module, tests, and linked-render specification")
